import { getRuntimeEnvEntries } from "../../../runtime-env-entries.mjs";
//#region src/internal/builders/vite/plugins/add-runtime-env-entries.ts
function addRuntimeEnvEntries(config) {
	return {
		name: "wxt:add-runtime-env-entries",
		config() {
			const define = {};
			for (const global of getRuntimeEnvEntries(config)) define[`import.meta.env.${global.name}`] = JSON.stringify(global.value);
			return { define };
		}
	};
}
//#endregion
export { addRuntimeEnvEntries };
